def wait_until_ready(check, timeout_s, interval_s, clock, sleep):
    start = clock()
    attempts = 0
    while True:
        attempts += 1
        if check():
            return attempts
        if clock() - start + interval_s > timeout_s:
            raise TimeoutError(f'not ready after {attempts} attempts')
        sleep(interval_s)

