def select_tests(tests, stage):
    if stage == 'pr':
        return [t['name'] for t in tests if 'smoke' in t['tags']]
    if stage == 'nightly':
        return [t['name'] for t in tests]
    if stage == 'deploy':
        return [t['name'] for t in tests if 'smoke' in t['tags'] and 'destructive' not in t['tags']]
    raise ValueError(stage)

